 int scenarioStep,scenarioUnit;bool scenarioAnswered;
 void Scenario(int id){scenarioUnit=id;scenarioStep=0;inLesson=true;ScenarioTurn();}
 void ScenarioTurn(){Clear();SetFocus(true);scenarioAnswered=false;content.Children.Add(Btn("×  العودة للمسار",()=>Navigate(Home)));Add(content,"مختبر الصفقات",30,Ink,true);Add(content,$"{Course.Units[scenarioUnit].Title}  •  الموقف {scenarioStep+1} / 3",15,Muted);var task=Cases[scenarioUnit][scenarioStep];content.Children.Add(Card(Text(task.Context,21),"#FFF3D2"));var chat=new StackPanel();Add(chat,"المورد",13,Green,true);Add(chat,task.Supplier,23,Ink,true).Ltr();chat.Children.Add(Btn("▶ استمع للمورد",()=>Speak(task.Supplier,false)));content.Children.Add(Card(chat));Add(content,"ما الرد الأنسب لتحقيق هدفك؟",20,Ink,true);var explanation=Text("",17);var proceed=Btn(scenarioStep<2?"الموقف التالي ←":"إنهاء المحاكاة",()=>{scenarioStep++;if(scenarioStep<3)ScenarioTurn();else{inLesson=false;Clear();int gain=S.CasesDone.Add(scenarioUnit)?30:5;S.Xp+=gain;Save();UpdateSide();Add(content,"صفقة موفّقة!",34,Green,true);Add(content,$"أنجزت ثلاثة مواقف تجارية  •  +{gain} نقطة",20);Add(content,"جرّب الآن قول الردود بصوتك دون النظر إليها.",18,Muted);content.Children.Add(Btn("العودة إلى الرحلة",Home,true));}},true);proceed.IsEnabled=false;foreach(var i in Enumerable.Range(0,3).OrderBy(_=>Random.Shared.Next())){int answer=i;var b=Btn(task.Choices[i],()=>{if(scenarioAnswered)return;if(answer==task.Correct){scenarioAnswered=true;explanation.Text="✓ "+task.Why;explanation.Foreground=Green;proceed.IsEnabled=true;}else{explanation.Text="فكّر في هدفك من هذا الموقف، ثم اختر ردًا يحققه.";explanation.Foreground=Brush("#B56148");}});b.FlowDirection=System.Windows.FlowDirection.LeftToRight;content.Children.Add(b);}content.Children.Add(explanation);content.Children.Add(proceed);}
